 tick(){if(!this.ctx||state!=='playing'||!config.sound)return;const now=this.ctx.currentTime;if(this.next<now-.2)this.next=now+.03;while(this.next<now+.12){const s=this.step%64,root=[110,130.81,87.31,98][Math.floor(s/16)],bass=[0,0,12,0,7,0,12,7][s%8];if(s%2===0)this.tone(root*Math.pow(2,bass/12),.14,'sawtooth',.2,this.music,this.next);const melody=[12,19,24,19,15,19,22,19,12,19,27,24,22,19,15,10];if(s%2===0)this.tone(root*Math.pow(2,melody[(s/2)%16]/12),.15,'square',boss?.105:.08,this.music,this.next);if(s%4===0)this.tone(150,.16,'sine',.7,this.music,this.next,38);if(s%8===4)this.hiss(.09,.18,this.next,this.music);this.hiss(.025,s%2===0?.07:.035,this.next,this.music);this.step++;this.next+=boss?.12:.14}}
 shoot(){this.tone(1450,.045,'square',.045,this.fx,0,550)}
 explosion(big=false){this.hiss(big?.3:.16,big?.8:.3);this.tone(big?90:150,big?.35:.16,'sawtooth',big?.4:.15,this.fx,0,30)}
 pickup(){[659,880,1318].forEach((f,i)=>this.tone(f,.14,'sine',.3,this.fx,this.ctx?this.ctx.currentTime+i*.065:0))}
