 c.shadowBlur=0;c.shadowOffsetY=0;
 poly(c,[[-9,-34],[-22,3],[-54,29],[-55,34],[-15,22],[-7,10],[7,10],[15,22],[55,34],[54,29],[22,3],[9,-34],[0,-69]],metal,'#b4ccca88',.7);
