 c.fillStyle=accent;c.fillRect(-3,24,6,12);line(c,0,39,0,57,'#203949',2);c.fillStyle='#eff4df';c.fillRect(-2,27,4,2);
 if(heavy){poly(c,[[-56,0],[-70,20],[-67,49],[-45,42],[-30,5]],metal,'#e6c3a3');poly(c,[[56,0],[70,20],[67,49],[45,42],[30,5]],metal,'#e6c3a3')}
