const cloudCanvas=document.createElement('canvas');cloudCanvas.width=450;cloudCanvas.height=250;{let c=cloudCanvas.getContext('2d');for(let i=0;i<14;i++){const x=80+Math.sin(i*17)*90+i*14,y=125+Math.cos(i*9)*45,g=c.createRadialGradient(x,y,1,x,y,60);g.addColorStop(0,'#deeff42e');g.addColorStop(.5,'#d3e9ef1c');g.addColorStop(1,'#bcdce900');c.fillStyle=g;c.fillRect(x-60,y-60,120,120)}}
function background(dt){scroll+=dt*(state==='playing'?65:24);const tile=terrains[sector],off=scroll%1500;ctx.drawImage(tile,0,off-1500);ctx.drawImage(tile,0,off);ctx.save();ctx.globalAlpha=sector===2?.35:.7;for(let i=0;i<3;i++){const y=((scroll*1.6+i*520)%1500)-300;ctx.drawImage(cloudCanvas,Math.sin(i*7+clock*.025)*90-50,y)}ctx.restore();const vignette=ctx.createRadialGradient(270,440,140,270,460,650);vignette.addColorStop(0,'#03132100');vignette.addColorStop(1,'#020b2166');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H)}
function announce(title,sub='',duration=3){$('banner').innerHTML=title+(sub?'<small>'+sub+'</small>':'');$('banner').classList.add('visible');bannerTimer=duration}
function addScore(v){score+=v;if(score>best){best=score;updateBest()}$('score').textContent=String(score).padStart(6,'0')}
let hudSignature='';
function hud(){ const signature=[lives,bombs,power,sector,state,boss?.hp??0].join(',');if(signature===hudSignature)return;hudSignature=signature; $('life').textContent='♥ '.repeat(Math.max(0,lives));$('bombCount').textContent=bombs;$('weapon').textContent='LV.'+power;document.querySelectorAll('.weapon-level i').forEach((e,i)=>e.classList.toggle('active',i<power));$('sectorLabel').textContent='SECTOR 0'+(sector+1);$('topStatus').textContent=state==='playing'?'IN FLIGHT':state==='paused'?'PAUSED':'STANDBY';$('bomb').disabled=bombs===0||state!=='playing';$('bottomHud').hidden=state==='title'||state==='ended';$('bossHud').hidden=!boss;if(boss){$('bossFill').style.width=clamp(boss.hp/boss.max*100,0,100)+'%';$('bossName').textContent=sectors[sector].boss}}
function reset(){runTime=0;sectorTime=0;sector=0;score=0;kills=0;shots=0;hits=0;lives=config.mode==='easy'?5:3;difficulty=config.mode==='easy'?.72:1;bombs=3;power=1;inv=2;fireClock=0;spawnClock=.6;wave=0;boss=null;bossSpawned=false;transition=0;scroll=0;shake=0;flash=0;enemies=[];bullets=[];hostiles=[];particles=[];pickups=[];rings=[];floats=[];player.x=270;player.y=785;pointer=null;keys.clear();$('score').textContent='000000';$('bossHud').hidden=true;hud()}
function start(){audio.init();reset();state='playing';$('titleScreen').hidden=true;$('pauseScreen').hidden=true;$('endScreen').hidden=true;audio.step=0;hud();announce('SECTOR 01','珊瑚海岸 / CORAL COAST',3);document.activeElement?.blur()}
function pause(){if(state!=='playing'&&state!=='paused')return;state=state==='playing'?'paused':'playing';$('pauseScreen').hidden=state!=='paused';keys.clear();pointer=null;hud();if(state==='playing')audio.init()}
function toTitle(){state='title';sector=0;boss=null;enemies=[];bullets=[];hostiles=[];pickups=[];particles=[];rings=[];$('titleScreen').hidden=false;$('pauseScreen').hidden=true;$('endScreen').hidden=true;$('bossHud').hidden=true;$('banner').classList.remove('visible');bannerTimer=0;persist();hud()}
function end(win){state='ended';$('endScreen').hidden=false;$('endTitle').textContent=win?'蒼穹，由你守護。':'任務結束';$('endEyebrow').textContent=win?'OPERATION COMPLETE':'MISSION REPORT';$('endMessage').textContent=win?'三個戰區，全數突破。王牌飛行員，歡迎返航。':'每一次出擊，都讓你更接近王牌。';$('endScore').textContent=String(score).padStart(6,'0');$('endMeta').textContent=`擊墜 ${kills} 架 · 航行 ${Math.floor(runTime/60)}:${String(Math.floor(runTime%60)).padStart(2,'0')} · ${config.mode==='easy'?'休閒':'標準'}模式`;persist();hud();keys.clear();pointer=null;if(win){audio.pickup();audio.tone(1046,.8,'triangle',.3)}}
function burst(x,y,color='#ffbf76',count=22,big=false){for(let i=0;i<count;i++){let a=rand(0,TAU),v=rand(30,big?310:180);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,t:rand(.25,big?1.2:.65),max:1,color,size:rand(1,big?6:4)})}rings.push({x,y,r:3,t:big?.65:.3,max:big?.65:.3,color});if(particles.length>650)particles.splice(0,particles.length-650)}
