function drop(x,y,forced){const n=Math.random();if(forced||n<.21){const type=forced||(n<.13?'P':n<.18?'B':'+');pickups.push({x,y,type,t:0,r:19})}}
function killEnemy(e,bombKill=false){if(e.dead)return;e.dead=true;kills++;addScore(e.type==='heavy'?600:150);burst(e.x,e.y,'#ffd18a',e.type==='heavy'?36:19,e.type==='heavy');audio.explosion(e.type==='heavy');drop(e.x,e.y,e.drop?'P':null);if(!bombKill)float(e.type==='heavy'?'+600':'+150',e.x,e.y)}
