function fire(){const level=power;for(let i=0;i<level+1;i++){const a=(i-level/2)*.085;bullets.push({x:player.x+(i-level/2)*11,y:player.y-38,vx:Math.sin(a)*710,vy:-Math.cos(a)*850,r:4,damage:1})}shots+=level+1;audio.shoot()}
function enemyFire(e){const speed=(125+sector*24)*difficulty;const a=Math.atan2(player.y-e.y,player.x-e.x);for(let i=0;i<(e.type==='heavy'?3:1);i++){const angle=a+(i-1)*(e.type==='heavy'?.23:0);hostiles.push({x:e.x,y:e.y+25,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r:5,color:'#ff9b7c'})}}
function spawnWave(){wave++;const type=wave%5===0?'heavy':'enemy';if(type==='heavy'){enemies.push({x:rand(110,430),base:270,y:-80,hp:30+sector*10,type,r:32,t:0,shot:1.3,drop:true})}else{const count=3+sector,side=wave%2?-1:1,base=rand(120,420);for(let i=0;i<count;i++){enemies.push({x:clamp(base+i*side*50,45,495),base:clamp(base+i*side*50,45,495),y:-60-i*65,hp:3+sector*2,type,r:20,t:i*.2,shot:rand(1.4,2.5),pattern:wave%3,side,drop:i===count-1&&wave%3===0})}}}
function spawnBoss(){bossSpawned=true;enemies.forEach(e=>{e.y=1100});hostiles=[];boss={x:270,y:-150,t:0,hp:480+sector*220,max:480+sector*220,shot:2,phase:0,r:95};audio.warning();announce('WARNING','強敵接近 / '+sectors[sector].boss,3.5);hud()}
